SourceCode.Declaration:
class XAPI_AutomateScripts
{

    private CustAccount accNum;
    private EXU_InstNum instNum;
    private EXU_ContractNum contractNum;

}

Method.Source:
public static void main(Args _args)
{
    XAPI_AutomateScripts automateScripts = XAPI_AutomateScripts::construct();

    automateScripts.parmCustomerAccount(XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, "CustAccount"));
    automateScripts.parmInstNum(XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateInstallation, "InstNum"));
    automateScripts.parmContractNum(XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateContract, "ContractNum"));

    XAPI_APILogTable::archive();
    automateScripts.execute();
}

private void deleteAll()
{
    ttsbegin;
    // Delete Contract Parts
    EXU_ContractTable contractTable = EXU_ContractTable::find(contractNum, true);
    if(contractTable.RecId)
    {

        contractTable.delete();
        info(strFmt("Deleted Contract: %1", contractNum));
    }
    else
    {
        info("No Contract Number provided — skipped deleting Contract and Contract Parts.");
    }


    // Delete Installations

    //EXU_DeliveryCategoryTable delCat;    
    EXU_DelPoint delPoint;
     select firstonly forupdate delPoint
        where delPoint.AttachmentNum == instNum;

    if(delPoint.RecId)
    {
        delPoint.delete();
        info(strFmt("Deleted Delivery Points for Customer: %1", accNum));
    }
    else
    {
        info("No Customer Account provided — skipped deleting Delivery Points.");
    }


    EXU_UtilityInstallation uinst;
    select firstonly forupdate uinst
        where uinst.InstNum == instNum;

    if(uinst.RecId)
    {

        uinst.delete();

        info(strFmt("Deleted Utility Installations for Customer: %1", accNum));
    }
    else
    {
        info("No Customer Account provided — skipped deleting Utility Installations.");
    }


    EXU_Installation inst = EXU_Installation::find(instNum, true);

    if(inst.RecId)
    {
        inst.delete();
        info(strFmt("Deleted Installations for Customer: %1", accNum));
    }
    else
    {
        info("No Customer Account provided — skipped deleting Installations.");
    }


    // Delete Customer
    CustTable custTable = CustTable::find(accNum, true);

    if (custTable.RecId)
    {
        custTable.delete();
        info(strFmt("Deleted Customer: %1", accNum));
    }
    else
    {
        info(strFmt("Customer '%1' does not exist — skipped.", accNum));
    }


    XAPI_NewContractDelDataGen::main(null);
    XAPI_NewInstallationDelDataGen::main(null);
    XAPI_NewCustomerDelDataGen::main(null);

    ttscommit;

}

public void execute()
{
    this.deleteAll();

    xapi_api_callautomator auto = xapi_api_callautomator::construct();

    // 1. create customer
    xapi_newcustomerdatagen::main(null);
    auto.callcreatecustapi();

    // 2. create installation for the customer
    xapi_newinstallationdatagen::main(null);
    auto.callinstallationapi();

    // 3. create contract for the installation
    xapi_newcontractdatagen::main(null);
    auto.callcontractapi("", "", "");

}

public CustAccount parmCustomerAccount(CustAccount _accNum = accNum)
{
    accNum = _accNum;
    return accNum;
}

public EXU_InstNum parmInstNum(EXU_InstNum _instNum = instNum)
{
    instNum = _instNum;
    return instNum;
}

public EXU_ContractNum parmContractNum(EXU_ContractNum _contractNum = contractNum)
{
    contractNum = _contractNum;
    return contractNum;
}

public static XAPI_AutomateScripts construct() 
{
    XAPI_AutomateScripts instance = new XAPI_AutomateScripts();
    return instance;
}
